#include "core/github_auth.h"

const char *runner_github_setup_instructions(void)
{
    return "GITHUB BROWSER SIGN-IN SETUP\n\nRunner Monitor needs a GitHub OAuth application identity for browser sign-in. A project Client ID can be shared by all installations. If you already have a Runner Monitor OAuth app, use its public Client ID below; you do not need to register another one.\n\n1. Select Open GitHub registration and sign in to your GitHub account.\n   https://github.com/settings/applications/new\n   You can also find this at Settings > Developer settings > OAuth apps > New OAuth App.\n\n2. Enter these exact values:\n   Application name: Runner Monitor\n   Homepage URL: https://github.com/Infiltrator-Projects/RunnerScope\n   Application description: Desktop monitor for GitHub Actions runners\n   Authorization callback URL: http://127.0.0.1/\n\n3. Enable Device Flow. Leave GitHub's other defaults unchanged. The callback address is required by the form; device sign-in does not use a callback server.\n\n4. Select Register application. On the application's page, copy the value labelled Client ID. No client secret or personal access token is needed.\n\n5. Return to this window, paste the Client ID into Public Client ID, and select Save and sign in. Runner Monitor remembers it across restarts and upgrades.\n\n6. GitHub opens in your browser. Enter the one-time code displayed in Runner Monitor and approve the requested organisation and repository access. Runner Monitor checks access to your organisation's runners automatically.\n\nUse an account with permission to administer the monitored organisation's runners. If your organisation restricts OAuth apps or uses SSO, approve the app for that organisation in GitHub. If a saved sign-in expires or is revoked, choose Sign in with GitHub again; the Client ID stays saved.\n";
}
